(function(){var M=["janeiro","fevereiro","março","abril","maio","junho","julho","agosto","setembro","outubro","novembro","dezembro"];function f(d){return d.getDate()}var n=new Date(),a=new Date(n.getTime()+5*864e5),b=new Date(n.getTime()+13*864e5);var t=a.getMonth()===b.getMonth()?f(a)+" e "+f(b)+" de "+M[b.getMonth()]:f(a)+" de "+M[a.getMonth()]+" e "+f(b)+" de "+M[b.getMonth()];document.querySelectorAll("[data-eta]").forEach(function(e){e.textContent=t});})();